std::string ErrorList::format() const{ std::ostringstream o; for(auto& e:entries_){ o<<static_cast<int>(e.code)<<": "<<e.message; if(!e.context.empty()) o<<" ("<<e.context<<")"; o<<'\n'; } return o.str(); }
