std::vector<ObjectId> Scene::rootNodes() const{ std::vector<ObjectId> r; for(auto& n:nodes_) if(!isValidId(n.parentId())||!findNode(n.parentId())) r.push_back(n.id()); return r; } void Scene::rebuildIndexes(){ meshIndex_.clear();materialIndex_.clear();textureIndex_.clear();animationIndex_.clear();skeletonIndex_.clear();cameraIndex_.clear();lightIndex_.clear();nodeIndex_.clear(); for(std::size_t i=0;i<meshes_.size();++i)meshIndex_[meshes_[i].id()]=i; for(std::size_t i=0;i<materials_.size();++i)materialIndex_[materials_[i].id()]=i; for(std::size_t i=0;i<textures_.size();++i)textureIndex_[textures_[i].id()]=i; for(std::size_t i=0;i<animations_.size();++i)animationIndex_[animations_[i].id()]=i; for(std::size_t i=0;i<skeletons_.size();++i)skeletonIndex_[skeletons_[i].id()]=i; for(std::size_t i=0;i<cameras_.size();++i)cameraIndex_[cameras_[i].id()]=i; for(std::size_t i=0;i<lights_.size();++i)lightIndex_[lights_[i].id()]=i; for(std::size_t i=0;i<nodes_.size();++i)nodeIndex_[nodes_[i].id()]=i; }
void Scene::traverse(const NodeVisitor& v) const{ for(auto id:rootNodes()) traverseFrom(id,Mat4::identity(),v); } void Scene::traverseFrom(ObjectId id,const Mat4& p,const NodeVisitor& v) const{ auto* n=findNode(id); if(!n)return; Mat4 w=p*n->localTransform().toMatrix(); v(*n,w); for(auto c:n->children()) traverseFrom(c,w,v); } Mat4 Scene::worldTransform(ObjectId id) const{ auto* n=findNode(id); if(!n)return Mat4::identity(); if(!isValidId(n->parentId())) return n->localTransform().toMatrix(); return worldTransform(n->parentId())*n->localTransform().toMatrix(); }

namespace compression { std::vector<std::uint8_t> compressRle(const std::vector<std::uint8_t>& in){ std::vector<std::uint8_t> out; for(std::size_t i=0;i<in.size();){ auto v=in[i]; std::size_t run=1; while(i+run<in.size()&&in[i+run]==v&&run<127)++run; if(run>=3){out.push_back(0x80|static_cast<std::uint8_t>(run));out.push_back(v);i+=run;} else { auto s=i; i+=run; while(i<in.size()&&i-s<127){std::size_t nr=1;while(i+nr<in.size()&&in[i+nr]==in[i]&&nr<127)++nr; if(nr>=3)break; i+=nr;} out.push_back(static_cast<std::uint8_t>(i-s)); out.insert(out.end(),in.begin()+static_cast<std::ptrdiff_t>(s),in.begin()+static_cast<std::ptrdiff_t>(i)); }} return out;} Result<std::vector<std::uint8_t>> decompressRle(const std::vector<std::uint8_t>& in,std::size_t expected){ std::vector<std::uint8_t> out; out.reserve(expected); for(std::size_t i=0;i<in.size();){ auto tag=in[i++]; auto count=tag&0x7f; if(!count)return Error{ErrorCode::CompressionError,"zero length RLE packet","compression"}; if(tag&0x80){ if(i>=in.size()) return Error{ErrorCode::TruncatedInput,"missing RLE value","compression"}; out.insert(out.end(),count,in[i++]); } else { if(i+count>in.size()) return Error{ErrorCode::TruncatedInput,"literal exceeds input","compression"}; out.insert(out.end(),in.begin()+static_cast<std::ptrdiff_t>(i),in.begin()+static_cast<std::ptrdiff_t>(i+count)); i+=count; } if(out.size()>expected) return Error{ErrorCode::CompressionError,"output too large","compression"}; } if(out.size()!=expected) return Error{ErrorCode::CompressionError,"output size mismatch","compression"}; return out;} bool shouldCompress(const std::vector<std::uint8_t>& in){ return in.size()>=64 && compressRle(in).size()+8<in.size(); } }

namespace parser {
SceneParser::SceneParser(ParserOptions o):options_(o){} Result<Scene> SceneParser::parse(const std::vector<std::uint8_t>& b) const{return parse(b.data(),b.size());} Result<Scene> SceneParser::parse(const std::uint8_t* d,std::size_t s) const{ ParseContext c; c.options=options_; c.input=d; c.inputSize=s; if(auto r=parseHeader(c);!r)return r.error(); if(auto r=validateVersion(c);!r)return r.error(); if(auto r=discoverSections(c);!r)return r.error(); if(auto r=validateOffsets(c);!r)return r.error(); if(auto r=createObjects(c);!r)return r.error(); if(auto r=resolveReferences(c);!r)return r.error(); if(auto r=loadAnimations(c);!r)return r.error(); if(auto r=constructScene(c);!r)return r.error(); return c.scene; }
Result<void> parseHeader(ParseContext& c){ if(c.inputSize<sizeof(format::FileHeader)) return Error{ErrorCode::TruncatedInput,"input shorter than file header","header stage"}; BinaryReader r(c.input,c.inputSize); auto h=r.readPod<format::FileHeader>(); if(!h)return h.error(); c.header=h.value(); if(std::memcmp(c.header.magic,format::kMagic.data(),4)!=0) return Error{ErrorCode::InvalidMagic,"file magic is not BSEN","header stage"}; if(c.header.headerSize<sizeof(format::FileHeader)) return Error{ErrorCode::InvalidSectionTable,"header size too small","header stage"}; return {}; }
Result<void> validateVersion(ParseContext& c){ if(c.header.majorVersion!=format::kMajorVersion) return Error{ErrorCode::UnsupportedVersion,"unsupported major version","version stage"}; return {}; }
Result<void> discoverSections(ParseContext& c){ auto tableSize=c.header.sectionCount*sizeof(format::SectionRecord); if(c.header.sectionTableOffset>c.inputSize||tableSize>c.inputSize-c.header.sectionTableOffset) return Error{ErrorCode::InvalidSectionTable,"section table exceeds file","section stage"}; BinaryReader r(c.input,c.inputSize); r.seek(static_cast<std::size_t>(c.header.sectionTableOffset)); for(std::uint32_t i=0;i<c.header.sectionCount;++i){ auto rec=r.readPod<format::SectionRecord>(); if(!rec)return rec.error(); if(!format::isKnownSection(rec.value().kind)&&!c.options.allowUnknownOptionalSections) return Error{ErrorCode::InvalidSectionTable,"unknown section","section stage"}; c.sections.push_back(rec.value()); } return {}; }
Result<void> validateOffsets(ParseContext& c){ for(auto& s:c.sections){ if(s.offset>c.inputSize||s.size>c.inputSize-s.offset) return Error{ErrorCode::InvalidOffset,"section outside file","offset stage"}; if(s.uncompressedSize>c.options.maximumSectionSize) return Error{ErrorCode::InvalidOffset,"section too large","offset stage"}; BinaryReader r(c.input+s.offset,static_cast<std::size_t>(s.size)); auto bytes=r.readBytes(static_cast<std::size_t>(s.size)); if(!bytes)return bytes.error(); RawSection raw; raw.record=s; if(s.flags&format::SectionFlagCompressed){ auto dec=compression::decompressRle(bytes.value(),static_cast<std::size_t>(s.uncompressedSize)); if(!dec)return dec.error(); raw.data=std::move(dec.value()); } else raw.data=std::move(bytes.value()); c.sectionData[s.kind]=std::move(raw); } return {}; }
Result<void> createObjects(ParseContext& c){
 if(auto it=c.sectionData.find(static_cast<std::uint32_t>(format::SectionKind::Meshes));it!=c.sectionData.end()){ auto r=readCounted(it->second,[&](BinaryReader& rd)->Result<void>{ auto id=rd.readPod<std::uint32_t>(); if(!id)return id.error(); auto n=readName(rd); if(!n)return n.error(); auto mat=rd.readPod<std::uint32_t>(); if(!mat)return mat.error(); auto vc=rd.readPod<std::uint32_t>(); if(!vc)return vc.error(); auto ic=rd.readPod<std::uint32_t>(); if(!ic)return ic.error(); Mesh m(id.value(),n.value()); m.setMaterialId(mat.value()); for(std::uint32_t i=0;i<vc.value();++i){auto v=rd.readPod<Vertex>(); if(!v)return v.error(); m.vertices().push_back(v.value());} for(std::uint32_t i=0;i<ic.value();++i){auto idx=rd.readPod<std::uint32_t>(); if(!idx)return idx.error(); m.indices().push_back(idx.value());} c.scene.addMesh(std::move(m)); return {};}); if(!r)return r.error(); }
 if(auto it=c.sectionData.find(static_cast<std::uint32_t>(format::SectionKind::Materials));it!=c.sectionData.end()){ auto r=readCounted(it->second,[&](BinaryReader& rd)->Result<void>{ auto id=rd.readPod<std::uint32_t>(); if(!id)return id.error(); auto n=readName(rd); if(!n)return n.error(); auto col=rd.readPod<Vec4>(); if(!col)return col.error(); auto me=rd.readPod<float>(); if(!me)return me.error(); auto ro=rd.readPod<float>(); if(!ro)return ro.error(); auto tex=rd.readPod<std::uint32_t>(); if(!tex)return tex.error(); Material m(id.value(),n.value()); m.setBaseColor(col.value()); m.setMetallic(me.value()); m.setRoughness(ro.value()); if(isValidId(tex.value()))m.setTextureSlot("baseColor",tex.value()); c.scene.addMaterial(std::move(m)); return {};}); if(!r)return r.error(); }
 if(auto it=c.sectionData.find(static_cast<std::uint32_t>(format::SectionKind::Textures));it!=c.sectionData.end()){ auto r=readCounted(it->second,[&](BinaryReader& rd)->Result<void>{ auto id=rd.readPod<std::uint32_t>(); if(!id)return id.error(); auto n=readName(rd); if(!n)return n.error(); auto uri=readName(rd); if(!uri)return uri.error(); auto w=rd.readPod<std::uint32_t>(); if(!w)return w.error(); auto h=rd.readPod<std::uint32_t>(); if(!h)return h.error(); auto f=rd.readPod<std::uint32_t>(); if(!f)return f.error(); TextureMetadata t(id.value(),n.value(),uri.value()); t.setDimensions(w.value(),h.value()); t.setFormat(static_cast<TextureFormat>(f.value())); c.scene.addTexture(std::move(t)); return {};}); if(!r)return r.error(); }
 if(auto it=c.sectionData.find(static_cast<std::uint32_t>(format::SectionKind::Nodes));it!=c.sectionData.end()){ auto r=readCounted(it->second,[&](BinaryReader& rd)->Result<void>{ auto id=rd.readPod<std::uint32_t>(); if(!id)return id.error(); auto n=readName(rd); if(!n)return n.error(); auto parent=rd.readPod<std::uint32_t>(); if(!parent)return parent.error(); auto mesh=rd.readPod<std::uint32_t>(); if(!mesh)return mesh.error(); auto skel=rd.readPod<std::uint32_t>(); if(!skel)return skel.error(); auto cam=rd.readPod<std::uint32_t>(); if(!cam)return cam.error(); auto light=rd.readPod<std::uint32_t>(); if(!light)return light.error(); auto tr=rd.readPod<Transform>(); if(!tr)return tr.error(); SceneNode node(id.value(),n.value()); node.setParentId(parent.value()); node.setMeshId(mesh.value()); node.setSkeletonId(skel.value()); node.setCameraId(cam.value()); node.setLightId(light.value()); node.localTransform()=tr.value(); c.scene.addNode(std::move(node)); return {};}); if(!r)return r.error(); }
 return {}; }
Result<void> resolveReferences(ParseContext& c){ for(auto& n:c.scene.nodes()){ if(isValidId(n.parentId())){ auto* p=c.scene.findNode(n.parentId()); if(!p)return Error{ErrorCode::MissingReference,"node parent does not exist","reference stage"}; if(std::find(p->children().begin(),p->children().end(),n.id())==p->children().end()) p->children().push_back(n.id()); }} return {}; }
Result<void> loadAnimations(ParseContext& c){ auto it=c.sectionData.find(static_cast<std::uint32_t>(format::SectionKind::Animations)); if(it==c.sectionData.end())return {}; BinaryReader rd(it->second.data); auto count=rd.readPod<std::uint32_t>(); if(!count)return count.error(); for(std::uint32_t i=0;i<count.value();++i){ auto id=rd.readPod<std::uint32_t>(); if(!id)return id.error(); auto n=readName(rd); if(!n)return n.error(); auto dur=rd.readPod<float>(); if(!dur)return dur.error(); auto cc=rd.readPod<std::uint32_t>(); if(!cc)return cc.error(); AnimationClip clip(id.value(),n.value()); clip.setDuration(dur.value()); for(std::uint32_t cidx=0;cidx<cc.value();++cidx){ auto target=rd.readPod<std::uint32_t>(); if(!target)return target.error(); AnimationChannel ch(target.value()); auto tc=rd.readPod<std::uint32_t>(); if(!tc)return tc.error(); for(std::uint32_t k=0;k<tc.value();++k){auto x=rd.readPod<KeyframeVec3>(); if(!x)return x.error(); ch.translations().push_back(x.value());} auto rc=rd.readPod<std::uint32_t>(); if(!rc)return rc.error(); for(std::uint32_t k=0;k<rc.value();++k){auto x=rd.readPod<KeyframeVec4>(); if(!x)return x.error(); ch.rotations().push_back(x.value());} auto sc=rd.readPod<std::uint32_t>(); if(!sc)return sc.error(); for(std::uint32_t k=0;k<sc.value();++k){auto x=rd.readPod<KeyframeVec3>(); if(!x)return x.error(); ch.scales().push_back(x.value());} clip.channels().push_back(std::move(ch)); } c.scene.addAnimation(std::move(clip)); } return {}; }
Result<void> constructScene(ParseContext& c){ c.scene.rebuildIndexes(); return {}; }
}

namespace serialization {
SceneSerializer::SceneSerializer(SerializerOptions o):options_(o){}
Result<std::vector<std::uint8_t>> SceneSerializer::serialize(const Scene& s) const{ std::vector<SectionBlob> blobs; { BinaryWriter w; w.writePod<std::uint32_t>(s.meshes().size()); for(auto& m:s.meshes()){ w.writePod(m.id()); writeName(w,m.name()); w.writePod(m.materialId()); w.writePod<std::uint32_t>(m.vertices().size()); w.writePod<std::uint32_t>(m.indices().size()); for(auto& v:m.vertices())w.writePod(v); for(auto i:m.indices())w.writePod(i);} blobs.push_back(makeSection(format::SectionKind::Meshes,w,options_.compressLargeSections)); } { BinaryWriter w; w.writePod<std::uint32_t>(s.materials().size()); for(auto& m:s.materials()){ w.writePod(m.id()); writeName(w,m.name()); w.writePod(m.baseColor()); w.writePod(m.metallic()); w.writePod(m.roughness()); w.writePod(m.textureForSlot("baseColor")); } blobs.push_back(makeSection(format::SectionKind::Materials,w,options_.compressLargeSections)); } { BinaryWriter w; w.writePod<std::uint32_t>(s.textures().size()); for(auto& t:s.textures()){ w.writePod(t.id()); writeName(w,t.name()); writeName(w,t.uri()); w.writePod(t.width()); w.writePod(t.height()); w.writePod(static_cast<std::uint32_t>(t.format())); } blobs.push_back(makeSection(format::SectionKind::Textures,w,options_.compressLargeSections)); } { BinaryWriter w; w.writePod<std::uint32_t>(s.nodes().size()); for(auto& n:s.nodes()){ w.writePod(n.id()); writeName(w,n.name()); w.writePod(n.parentId()); w.writePod(n.meshId()); w.writePod(n.skeletonId()); w.writePod(n.cameraId()); w.writePod(n.lightId()); w.writePod(n.localTransform()); } blobs.push_back(makeSection(format::SectionKind::Nodes,w,options_.compressLargeSections)); } { BinaryWriter w; w.writePod<std::uint32_t>(s.animations().size()); for(auto& a:s.animations()){ w.writePod(a.id()); writeName(w,a.name()); w.writePod(a.duration()); w.writePod<std::uint32_t>(a.channels().size()); for(auto& ch:a.channels()){ w.writePod(ch.targetNode()); w.writePod<std::uint32_t>(ch.translations().size()); for(auto& k:ch.translations())w.writePod(k); w.writePod<std::uint32_t>(ch.rotations().size()); for(auto& k:ch.rotations())w.writePod(k); w.writePod<std::uint32_t>(ch.scales().size()); for(auto& k:ch.scales())w.writePod(k); }} blobs.push_back(makeSection(format::SectionKind::Animations,w,options_.compressLargeSections)); } for(auto k:{format::SectionKind::Skeletons,format::SectionKind::Cameras,format::SectionKind::Lights,format::SectionKind::Metadata,format::SectionKind::Strings}){ BinaryWriter w; w.writePod<std::uint32_t>(0); blobs.push_back(makeSection(k,w,false)); } BinaryWriter out; format::FileHeader h{}; std::memcpy(h.magic,format::kMagic.data(),4); h.majorVersion=format::kMajorVersion; h.minorVersion=format::kMinorVersion; h.headerSize=sizeof(h); h.sectionCount=static_cast<std::uint32_t>(blobs.size()); h.sectionTableOffset=sizeof(h); out.writePod(h); auto table=out.position(); for(std::size_t i=0;i<blobs.size();++i){ format::SectionRecord r{}; out.writePod(r); } std::vector<format::SectionRecord> records; for(auto& b:blobs){ out.align(options_.alignment); format::SectionRecord r{}; r.kind=static_cast<std::uint32_t>(b.kind); r.flags=b.flags; r.offset=out.position(); r.size=b.bytes.size(); r.uncompressedSize=b.uncompressedSize; out.writeBytes(b.bytes); records.push_back(r);} h.fileSize=out.position(); auto bytes=out.bytes(); for(std::size_t i=0;i<records.size();++i) std::memcpy(bytes.data()+table+i*sizeof(format::SectionRecord),&records[i],sizeof(format::SectionRecord)); h.checksum=options_.includeChecksum?util::fnv1a32(bytes):0; std::memcpy(bytes.data(),&h,sizeof(h)); return bytes; }
SceneDeserializer::SceneDeserializer(parser::ParserOptions o):parser_(o){} Result<Scene> SceneDeserializer::deserialize(const std::vector<std::uint8_t>& b) const{return parser_.parse(b);} }

namespace resource { bool ResourceCache::contains(const std::string& k) const{return entries_.find(k)!=entries_.end();} void ResourceCache::releaseUnused(){ for(auto it=entries_.begin();it!=entries_.end();){ if(it->second.value.use_count()==1){it=entries_.erase(it);++stats_.evictions;} else ++it;} stats_.liveResources=entries_.size(); } void ResourceCache::evict(const std::string& k){ if(entries_.erase(k))++stats_.evictions; stats_.liveResources=entries_.size(); } void ResourceCache::clear(){ stats_.evictions+=entries_.size(); entries_.clear(); stats_.liveResources=0;} CacheStats ResourceCache::stats() const{return stats_;} }
namespace validation { SceneValidator::SceneValidator(ValidationOptions o):options_(o){} ErrorList SceneValidator::validate(const Scene& s) const{ ErrorList e; std::unordered_set<ObjectId> nodes; for(auto& n:s.nodes()){ if(!nodes.insert(n.id()).second)e.add(ErrorCode::ValidationError,"duplicate node id",n.name()); if(options_.requireExistingReferences){ if(isValidId(n.parentId())&&!s.findNode(n.parentId()))e.add(ErrorCode::MissingReference,"missing parent",n.name()); if(isValidId(n.meshId())&&!s.findMesh(n.meshId()))e.add(ErrorCode::MissingReference,"missing mesh",n.name()); if(isValidId(n.skeletonId())&&!s.findSkeleton(n.skeletonId()))e.add(ErrorCode::MissingReference,"missing skeleton",n.name()); if(isValidId(n.cameraId())&&!s.findCamera(n.cameraId()))e.add(ErrorCode::MissingReference,"missing camera",n.name()); if(isValidId(n.lightId())&&!s.findLight(n.lightId()))e.add(ErrorCode::MissingReference,"missing light",n.name()); }} if(options_.requireValidMeshIndices){ for(auto& m:s.meshes()){ for(auto i:m.indices()) if(i>=m.vertices().size()){e.add(ErrorCode::ValidationError,"mesh index exceeds vertex count",m.name());break;} if(isValidId(m.materialId())&&!s.findMaterial(m.materialId()))e.add(ErrorCode::MissingReference,"missing material",m.name()); }} if(options_.requireAcyclicHierarchy){ for(auto& n:s.nodes()){ std::unordered_set<ObjectId> seen; ObjectId cur=n.id(); while(auto* node=s.findNode(cur)){ if(!seen.insert(cur).second){e.add(ErrorCode::ValidationError,"cycle in node hierarchy",n.name());break;} if(!isValidId(node->parentId()))break; cur=node->parentId(); }}} return e; } }
namespace util { std::uint32_t fnv1a32(const std::uint8_t* b,std::size_t s){ std::uint32_t h=2166136261u; for(std::size_t i=0;i<s;++i){h^=b[i];h*=16777619u;} return h;} std::uint32_t fnv1a32(const std::vector<std::uint8_t>& b){return fnv1a32(b.data(),b.size());} std::string normalizePath(std::string p){std::replace(p.begin(),p.end(),'\\','/');return p;} std::string basename(const std::string& p){auto x=p.find_last_of("/\\");return x==std::string::npos?p:p.substr(x+1);} }
